-- ---- Hand-written from here on -------------------------------------------------------------

-- The scope of one Ask AI connection, keyed by its backend PID, which SQL cannot change. Written
-- by acme_app from the session (never by the model) just before a run_sql call and deleted after.
CREATE TABLE app_private.ai_scope (
  backend_pid integer PRIMARY KEY,
  countries char(2)[] NOT NULL,
  expires_at timestamptz NOT NULL
);--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON app_private.ai_scope TO acme_app;--> statement-breakpoint

-- acme_ai_reader runs the model's SQL. It is its own LOGIN role, not a SET ROLE target of acme_app,
-- because RESET ROLE would climb back to the session user. Created NOLOGIN here; `npm run
-- db:roles` turns on LOGIN with a password from the environment (never in a migration).
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'acme_ai_reader') THEN
    CREATE ROLE acme_ai_reader NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION
      NOBYPASSRLS NOINHERIT CONNECTION LIMIT 4;
  END IF;
END
$$;--> statement-breakpoint
ALTER ROLE acme_ai_reader SET default_transaction_read_only = on;--> statement-breakpoint
ALTER ROLE acme_ai_reader SET statement_timeout = '5s';--> statement-breakpoint
ALTER ROLE acme_ai_reader SET idle_in_transaction_session_timeout = '10s';--> statement-breakpoint

-- No temporary tables for anyone but the app (PUBLIC has TEMP by default), no CREATE in public
-- (revoked in 0005).
DO $$
BEGIN
  EXECUTE format('REVOKE TEMPORARY ON DATABASE %I FROM PUBLIC', current_database());
  EXECUTE format('GRANT TEMPORARY ON DATABASE %I TO acme_app', current_database());
END
$$;--> statement-breakpoint

-- The reader's scope comes from ai_scope, never from a setting it could change with
-- set_config(). SECURITY DEFINER so the reader needs no grant on the table and only ever sees
-- its own connection's row.
CREATE FUNCTION app_private.ai_scope_countries() RETURNS char(2)[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT countries FROM app_private.ai_scope
   WHERE backend_pid = pg_backend_pid() AND expires_at > now()
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_private.ai_scope_countries() FROM PUBLIC;--> statement-breakpoint
-- acme_app needs EXECUTE too: scope_countries() below is inlined into its policies, and the
-- planner checks the call even on the branch acme_app never takes. Its own PID has no row.
GRANT EXECUTE ON FUNCTION app_private.ai_scope_countries() TO acme_ai_reader, acme_app;--> statement-breakpoint

-- One scope function for both roles, so every policy keeps a single country rule.
CREATE OR REPLACE FUNCTION app_private.scope_countries() RETURNS char(2)[]
LANGUAGE sql STABLE AS $$
  SELECT CASE
    WHEN session_user = 'acme_ai_reader' THEN app_private.ai_scope_countries()
    ELSE string_to_array(nullif(current_setting('app.countries', true), ''), ',')::char(2)[]
  END
$$;--> statement-breakpoint

-- What the model may read. Column grants keep names, emails and free-text notes out of its
-- reach in the database itself (decision #37): `select *` on employees fails for this role.
GRANT USAGE ON SCHEMA public, app_private TO acme_ai_reader;--> statement-breakpoint
GRANT SELECT (
  id, employee_code, country_code, job_title_id, department_id, hire_date, status,
  termination_date, termination_reason, salary_amount_minor, salary_currency,
  salary_effective_date, created_at, updated_at
) ON employees TO acme_ai_reader;--> statement-breakpoint
GRANT SELECT (
  id, employee_id, country_code, amount_minor, previous_amount_minor, currency, effective_date,
  reason, created_at
) ON salary_changes TO acme_ai_reader;--> statement-breakpoint
GRANT SELECT ON countries, job_titles, departments, fx_rates TO acme_ai_reader;--> statement-breakpoint

CREATE POLICY employees_ai_read ON employees FOR SELECT TO acme_ai_reader
  USING (country_code = ANY ((SELECT app_private.scope_countries())::char(2)[]));--> statement-breakpoint
CREATE POLICY salary_changes_ai_read ON salary_changes FOR SELECT TO acme_ai_reader
  USING (country_code = ANY ((SELECT app_private.scope_countries())::char(2)[]));--> statement-breakpoint

-- The API's own access to the conversation tables. Messages are append-only; drafts are only
-- updated to mark them applied.
GRANT SELECT, INSERT, UPDATE ON ai_conversations TO acme_app;--> statement-breakpoint
GRANT SELECT, INSERT ON ai_messages TO acme_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON ai_salary_drafts TO acme_app;--> statement-breakpoint

-- Own conversations only; a draft also needs its employee to be in scope.
ALTER TABLE ai_conversations ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY ai_conversations_own ON ai_conversations FOR ALL TO acme_app
  USING (user_id = (SELECT app_private.current_user_id()))
  WITH CHECK (user_id = (SELECT app_private.current_user_id()));--> statement-breakpoint
ALTER TABLE ai_messages ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY ai_messages_own ON ai_messages FOR ALL TO acme_app
  USING (EXISTS (SELECT 1 FROM ai_conversations c WHERE c.id = conversation_id))
  WITH CHECK (EXISTS (SELECT 1 FROM ai_conversations c WHERE c.id = conversation_id));--> statement-breakpoint
ALTER TABLE ai_salary_drafts ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY ai_salary_drafts_own ON ai_salary_drafts FOR ALL TO acme_app
  USING (
    EXISTS (SELECT 1 FROM ai_conversations c WHERE c.id = conversation_id)
    AND EXISTS (SELECT 1 FROM employees e WHERE e.id = employee_id)
  )
  WITH CHECK (
    EXISTS (SELECT 1 FROM ai_conversations c WHERE c.id = conversation_id)
    AND EXISTS (SELECT 1 FROM employees e WHERE e.id = employee_id)
  );
--> statement-breakpoint

-- The run_sql audit log: append-only for the API, invisible to the reader. You see your own runs;
-- an all-country role sees every run (the only route also needs audit:read), like audit_events.
GRANT SELECT, INSERT ON ai_sql_runs TO acme_app;--> statement-breakpoint
ALTER TABLE ai_sql_runs ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY ai_sql_runs_read ON ai_sql_runs FOR SELECT TO acme_app
  USING (
    user_id = (SELECT app_private.current_user_id())
    OR (SELECT app_private.scope_is_all())
  );--> statement-breakpoint
CREATE POLICY ai_sql_runs_insert ON ai_sql_runs FOR INSERT TO acme_app
  WITH CHECK (user_id = (SELECT app_private.current_user_id()));
